package fraymus.workspace;
import org.json.*;
import org.junit.Test;
import java.nio.file.*;
import java.util.*;
import java.awt.image.BufferedImage;
import java.io.*;
import javax.imageio.ImageIO;
import static org.junit.Assert.*;

public class WorldObservationStoreTest {
    static JSONObject pack()throws Exception{
        var image=new BufferedImage(240,160,BufferedImage.TYPE_INT_RGB);var random=new Random(36);for(int y=25;y<115;y++)for(int x=50;x<150;x++)image.setRGB(x,y,random.nextInt(0xffffff));var bytes=new ByteArrayOutputStream();ImageIO.write(image,"png",bytes);byte[] raw=bytes.toByteArray();var frames=new JSONArray();for(int i=0;i<9;i++)frames.put(new JSONObject().put("sourceFrame",i).put("image",Base64.getEncoder().encodeToString(raw)).put("imageSha256",PerceptionStore.hash(raw)));
        return new JSONObject().put("schema","fraynix-observation-frames-036-v1").put("title","Labelled synthetic static texture control").put("source","Generated Java test control, not real footage").put("license","Project test fixture").put("objects",new JSONArray().put(new JSONObject().put("key","subject").put("label","texture").put("box",new JSONArray(new double[]{50./240,25./160,150./240,115./160})))).put("frames",frames);
    }
    static JSONObject importPack(WorldObservationStore store,JSONObject pack)throws Exception{var meta=WorldFrames.copy(pack);var frames=meta.getJSONArray("frames");meta.remove("frames");String id=store.begin(meta.put("frameCount",frames.length())).getString("id");for(int i=0;i<frames.length();i++)store.upload(id,i,frames.getJSONObject(i));return store.commitImport(id);}
    static JSONObject arguments(WorldLedger ledger,String worldId,JSONObject d,int rev)throws Exception{var args=ledger.observe(worldId);args.remove("frame");args.remove("title");args.remove("status");return args.put("expectedObservationRevision",rev).put("datasetId",d.getString("id")).put("bindings",new JSONArray().put(new JSONObject().put("objectKey","subject").put("bodyId",ledger.observe(worldId).getJSONObject("frame").getJSONArray("bodies").getJSONObject(0).getString("id"))));}
    static JSONObject settled(WorldObservationStore s,String id)throws Exception{for(int i=0;i<3000;i++){var r=s.read(id);if(!r.getString("status").equals("running"))return r;Thread.sleep(10);}throw new AssertionError("Observation processing timed out");}
    @Test public void realProcessingRetainsSameWorldAndExactPixelsWithoutNativeCommit()throws Exception{
        Path root=Files.createTempDirectory("observations036-control-");var ledger=new WorldLedger(root);String worldId=ledger.create(WorldLedgerTest.source(WorldLedgerTest.suite().getJSONArray("cases").getJSONObject(0)),"Observation control").getString("id");var original=ledger.observe(worldId);JSONObject run,firstState;
        try(var s=new WorldObservationStore(root,ledger)){var d=importPack(s,pack());run=settled(s,s.start(arguments(ledger,worldId,d,0)).getString("id"));assertEquals(run.toString(),"completed",run.getString("status"));assertEquals(8,run.getJSONArray("trace").length());firstState=s.state(worldId);assertEquals(8,firstState.getJSONObject("estimate").getInt("revision"));assertTrue(original.similar(ledger.observe(worldId)));assertThrows(ConcurrentModificationException.class,()->s.start(arguments(ledger,worldId,d,0)));var export=s.export(run.getString("id"));byte[] raw;try(var gzip=new java.util.zip.GZIPInputStream(new ByteArrayInputStream(Base64.getDecoder().decode(export.getString("data"))))){raw=gzip.readAllBytes();}assertEquals(export.getString("rawSha256"),PerceptionStore.hash(raw));assertEquals(9,new JSONObject(new String(raw,java.nio.charset.StandardCharsets.UTF_8)).getJSONArray("images").length());}
        try(var restarted=new WorldObservationStore(root,new WorldLedger(root))){assertTrue(firstState.getJSONObject("estimate").similar(restarted.state(worldId).getJSONObject("estimate")));assertTrue(run.similar(restarted.read(run.getString("id"))));}
    }
    @Test public void refusesFutureAnnotationsAndDamagedPixelsAndPreservesCorruptStore()throws Exception{
        Path root=Files.createTempDirectory("observations036-negative-");var ledger=new WorldLedger(root);
        try(var s=new WorldObservationStore(root,ledger)){var p=pack();var meta=WorldFrames.copy(p);meta.remove("frames");String id=s.begin(meta.put("frameCount",9)).getString("id");var f=WorldFrames.copy(p.getJSONArray("frames").getJSONObject(0));assertThrows(IllegalArgumentException.class,()->s.upload(id,0,f.put("reference",new JSONArray())));f.remove("reference");f.put("imageSha256","0".repeat(64));assertThrows(IllegalStateException.class,()->s.upload(id,0,f));s.cancelImport(id);}
        var state=root.resolve("world-observations/state.json");String damaged=Files.readString(state).replace("\"sha256\":\"","\"sha256\":\"bad");Files.writeString(state,damaged);assertThrows(IllegalStateException.class,()->new WorldObservationStore(root,ledger));assertEquals(damaged,Files.readString(state));
    }
    @Test public void stopResumeSameProcessCannotLetOldWorkerCommitOrLoseRelatedEvidence()throws Exception{
        Path root=Files.createTempDirectory("observations036-resume-");var ledger=new WorldLedger(root);String worldId=ledger.create(WorldLedgerTest.source(WorldLedgerTest.suite().getJSONArray("cases").getJSONObject(0)),"Resume ownership control").getString("id");
        try(var s=new WorldObservationStore(root,ledger)){
            var d=importPack(s,pack());String id=s.start(arguments(ledger,worldId,d,0)).getString("id");s.stop(id);var prefix=s.read(id).getJSONArray("trace");s.resume(id);var finished=settled(s,id);assertEquals(finished.toString(),"completed",finished.getString("status"));assertEquals(1,finished.getInt("resumes"));for(int i=0;i<prefix.length();i++)assertTrue(prefix.getJSONObject(i).similar(finished.getJSONArray("trace").getJSONObject(i)));
            int rev=s.state(worldId).getJSONObject("estimate").getInt("revision");String second=s.start(arguments(ledger,worldId,d,rev)).getString("id");s.stop(second);var exported=s.export(id);byte[] raw;try(var gzip=new java.util.zip.GZIPInputStream(new ByteArrayInputStream(Base64.getDecoder().decode(exported.getString("data"))))){raw=gzip.readAllBytes();}var full=new JSONObject(new String(raw,java.nio.charset.StandardCharsets.UTF_8));assertEquals(1,full.getJSONArray("relatedRuns").length());assertEquals(second,full.getJSONArray("relatedRuns").getJSONObject(0).getString("id"));assertEquals(worldId,full.getJSONObject("nativeWorld").getString("id"));
        }
    }
    @Test public void completeVisualLossKeepsPredictionAndZeroRevisionRatherThanInventingState()throws Exception{
        Path root=Files.createTempDirectory("observations036-loss-");var ledger=new WorldLedger(root);String worldId=ledger.create(WorldLedgerTest.source(WorldLedgerTest.suite().getJSONArray("cases").getJSONObject(0)),"Loss control").getString("id");
        var p=pack();var blank=new ByteArrayOutputStream();ImageIO.write(new BufferedImage(240,160,BufferedImage.TYPE_INT_RGB),"png",blank);byte[] raw=blank.toByteArray();for(int i=1;i<p.getJSONArray("frames").length();i++)p.getJSONArray("frames").getJSONObject(i).put("image",Base64.getEncoder().encodeToString(raw)).put("imageSha256",PerceptionStore.hash(raw));
        try(var s=new WorldObservationStore(root,ledger)){var d=importPack(s,p);var run=settled(s,s.start(arguments(ledger,worldId,d,0)).getString("id"));assertEquals("completed",run.getString("status"));assertEquals(0,s.state(worldId).getJSONObject("estimate").getInt("revision"));for(Object item:run.getJSONArray("trace")){var e=((JSONObject)item).getJSONArray("objects").getJSONObject(0).getJSONObject("estimate");assertFalse(e.getBoolean("accepted"));assertEquals("predicted",e.getString("status"));}assertFalse(s.state(worldId).getBoolean("stale"));}
    }
    @Test public void distinctObjectsRetainSeparateBodyIdentitiesAndOneAtomicFrameRevision()throws Exception{
        Path root=Files.createTempDirectory("observations036-multiple-");var ledger=new WorldLedger(root);String worldId=ledger.create(WorldLedgerTest.source(WorldLedgerTest.suite().getJSONArray("cases").getJSONObject(0)),"Two-object software control").getString("id");var p=pack();
        var image=new BufferedImage(360,200,BufferedImage.TYPE_INT_RGB);var random=new Random(360);for(int k=0;k<2;k++)for(int y=40;y<150;y++)for(int x=30+k*180;x<140+k*180;x++)image.setRGB(x,y,random.nextInt(0xffffff));var bytes=new ByteArrayOutputStream();ImageIO.write(image,"png",bytes);byte[] raw=bytes.toByteArray();for(Object item:p.getJSONArray("frames"))((JSONObject)item).put("image",Base64.getEncoder().encodeToString(raw)).put("imageSha256",PerceptionStore.hash(raw));p.getJSONArray("objects").getJSONObject(0).put("box",new JSONArray(new double[]{30./360,.2,140./360,.75}));p.getJSONArray("objects").put(new JSONObject().put("key","other").put("label","second synthetic texture").put("box",new JSONArray(new double[]{210./360,.2,320./360,.75})));
        try(var s=new WorldObservationStore(root,ledger)){var d=importPack(s,p);var args=arguments(ledger,worldId,d,0);args.getJSONArray("bindings").put(new JSONObject().put("objectKey","other").put("bodyId",ledger.observe(worldId).getJSONObject("frame").getJSONArray("bodies").getJSONObject(1).getString("id")));var run=settled(s,s.start(args).getString("id"));assertEquals(run.toString(),"completed",run.getString("status"));var estimate=s.state(worldId).getJSONObject("estimate");assertEquals(2,estimate.getJSONObject("tracks").length());assertEquals(8,estimate.getInt("revision"));for(Object f:run.getJSONArray("trace"))assertEquals(2,((JSONObject)f).getJSONArray("objects").length());}
    }
}
